// ===== 설정 (여기만 수정하세요) =====
const COUNTRY = 'kr';                 // 앱스토어 국가
const PAGES_PER_APP = 10;            // 앱당 리뷰 페이지 수 (1페이지=최대 50개, 애플은 최대 10페이지=최근 500개까지만 제공)
// 앱 이름으로 검색해서 LG전자가 만든 앱만 자동으로 골라냅니다.
const SEARCH_TERMS = ['LG ThinQ', 'LG전자 서비스', 'LG전자'];
// 앱 ID를 이미 알면 여기에 직접 넣어도 됩니다. 예: ['993504342']
const EXTRA_APP_IDS = [];

return SEARCH_TERMS.map(term => ({ json: { term, country: COUNTRY, pages: PAGES_PER_APP, extraAppIds: EXTRA_APP_IDS } }));

// 검색 결과 → LG전자 앱만 골라 (앱 × 페이지) 요청 목록 만들기
const DEVELOPER_RE = /LG Electronics|LG전자|엘지전자/i;
const cfg = $('설정').first().json;
const apps = new Map();
for (const item of $input.all()) {
  for (const a of (item.json.results || [])) {
    if (!DEVELOPER_RE.test(a.artistName || a.sellerName || '')) continue;
    apps.set(String(a.trackId), { appId: String(a.trackId), appName: a.trackName, developer: a.artistName, rating: a.averageUserRating, ratingCount: a.userRatingCount });
  }
}
for (const id of (cfg.extraAppIds || [])) if (!apps.has(String(id))) apps.set(String(id), { appId: String(id), appName: '(직접 입력 ID ' + id + ')' });

const out = [];
for (const a of apps.values()) {
  for (let p = 1; p <= cfg.pages; p++) out.push({ json: { ...a, page: p, country: cfg.country } });
}
return out;

// 리뷰 펼치기 → 에어컨 관련 여부 / 증상 / '원인·다음행동 판단 어려움' 신호 태깅
const KEEP_ONLY_AIRCON = true;   // true: 에어컨 관련 리뷰만, false: 전체 리뷰
const MIN_LEN = 5;

const AIRCON = /에어컨|에어콘|휘센|whisen|냉방|냉난방|실외기|실내기|제습|오브제\s*에어|시스템\s*에어|창문형|이동식/i;
const SYMPTOMS = {
  '기기 연결·등록': /연결|등록|페어링|와이파이|wi-?fi|공유기|네트워크|오프라인|인식/i,
  '원격제어 안 됨': /원격|제어가?\s*안|작동\s*안|명령|반응\s*(이\s*)?없|안\s*켜|안\s*꺼|켜지지|꺼지지/,
  '앱 오류·먹통': /오류|에러|먹통|튕|멈춰|멈춤|로딩|접속|서버|강제\s*종료|안\s*열/,
  '로그인·계정': /로그인|계정|인증|비밀번호|탈퇴/,
  '업데이트 후 문제': /업데이트|업뎃|버전|개편|바뀐\s*후|바뀌고/,
  '알림': /알림|푸시/,
  '스마트진단': /진단|스마트\s*진단|자가\s*진단/,
  '냉방불량': /찬\s*바람이?\s*안|안\s*시원|시원하지\s*않|미지근|냉방이?\s*(약|안)/,
  '냄새': /냄새|쉰내|곰팡/,
  '물샘': /물이?\s*(새|샘|떨어)|누수|배수/,
  '소음': /소음|시끄|소리가/,
  '에러코드': /CH\s?-?\d{1,3}|에러\s*코드|오류\s*코드/i,
  '청소·필터·건조': /필터|청소|세척|건조/,
  '전기요금·에너지': /전기\s*(요금|세|료)|전력|에너지/,
  'AS·서비스': /a\s*\/?\s*s|서비스\s*센터|기사|수리|고객\s*센터|상담/i,
  'UI·사용성': /불편|복잡|찾기\s*(힘|어려)|어디에|메뉴|ui|ux|디자인/i,
};
const CAUSE_UNSURE = /왜\s*(그런|이러|이렇|안|자꾸|계속)|원인|뭐가\s*문제|무슨\s*문제|이유가|이유를|고장\s*인가|고장인지|정상\s*인가|정상인지|이게\s*맞나|모르겠/;
const ACTION_UNSURE = /어떻게\s*(해야|하면|하나요|하죠)|어떡하|어쩌죠|해야\s*(하나요|할까|되나|돼요|되나요)|불러야|(a\s*\/?\s*s|수리)\s*(를\s*)?(받아야|불러야|신청해야)|방법\s*(이|좀)?\s*(있|알려|없)|해결\s*(방법|이\s*안|못)|알려\s*주세요|도와\s*주세요|답이\s*없/i;
const ATTEMPTED = /해\s*봤|해봤|했는데|했는데도|했지만|그래도|여전히|그대로|재설치|삭제\s*후|지웠다|초기화|리셋|껐다\s*켜|재부팅|다시\s*등록|고객\s*센터에?\s*(전화|문의|연락)/;
const NEGATIVE = /짜증|화나|열받|최악|쓰레기|후회|환불|스트레스|답답|황당|어이없|실망|불편/;

const meta = $('앱 목록 정리').all();
const seen = new Set();
const rows = [];
const lab = x => (x && x.label !== undefined) ? x.label : '';

$input.all().forEach((item, i) => {
  const idx = (item.pairedItem && item.pairedItem.item !== undefined) ? item.pairedItem.item : i;
  const m = (meta[idx] || {}).json || {};
  let entries = (item.json.feed || {}).entry || [];
  if (!Array.isArray(entries)) entries = [entries];
  for (const e of entries) {
    if (!e['im:rating']) continue;                 // 앱 정보 항목 건너뜀
    const id = lab(e.id);
    if (seen.has(id)) continue;
    seen.add(id);
    const title = String(lab(e.title)).trim();
    const body = String(lab(e.content)).replace(/\s+/g, ' ').trim();
    const text = (title + ' ' + body).trim();
    if (body.length < MIN_LEN) continue;
    const aircon = AIRCON.test(text);
    if (KEEP_ONLY_AIRCON && !aircon) continue;

    const symptoms = Object.entries(SYMPTOMS).filter(([, re]) => re.test(text)).map(([k]) => k);
    const cause = CAUSE_UNSURE.test(text), action = ACTION_UNSURE.test(text);
    const rating = Number(lab(e['im:rating'])) || '';
    rows.push({ json: {
      '수집일': new Date().toISOString().slice(0, 10),
      '앱': m.appName || '',
      '앱ID': m.appId || '',
      '앱버전': lab(e['im:version']),
      '별점': rating,
      '작성일': String(lab(e.updated)).slice(0, 10),
      '리뷰제목': title,
      '리뷰내용': body,
      '도움돼요': Number(lab(e['im:voteSum'])) || 0,
      '에어컨관련': aircon ? 'Y' : '',
      '증상분류': symptoms.join(', '),
      '원인모름': cause ? 'Y' : '',
      '다음행동모름': action ? 'Y' : '',
      '질문형': /\?|까요|나요|가요|는지|인가요|되나요/.test(text) ? 'Y' : '',
      '이미시도한조치': ATTEMPTED.test(text) ? 'Y' : '',
      '부정감정': NEGATIVE.test(text) ? 'Y' : '',
      '저평점(1~2점)': rating && rating <= 2 ? 'Y' : '',
      '판단어려움후보': (cause || action) ? 'Y' : '',
      '리뷰ID': id,
    }});
  }
});

rows.sort((a, b) => (b.json['판단어려움후보'] === 'Y') - (a.json['판단어려움후보'] === 'Y') || (a.json['별점'] || 9) - (b.json['별점'] || 9));
return rows;
